167	        return Err(bad_request("records 不能为空批次"));
168	    }
169	
170	    let mut seen = HashSet::with_capacity(parsed.records.len());
171	    let mut batch: Vec<(String, Fields)> = Vec::with_capacity(parsed.records.len());
172	
173	    for (index, record) in parsed.records.into_iter().enumerate() {
174	        let fail = |message: &'static str| {
175	            (
176	                StatusCode::BAD_REQUEST,
177	                Json(ErrorBody {
178	                    error: message.to_owned(),
179	                    index: Some(index),
180	                }),
181	            )
182	        };
183	
184	        let mut object = match record {
185	            Value::Object(map) => map,
186	            _ => return Err(fail("每条记录必须是 JSON 对象")),
187	        };
188	
189	        let key = match object.remove("key") {
190	            Some(Value::String(key)) => key,
191	            Some(_) => return Err(fail("记录的 key 必须是字符串")),
192	            None => return Err(fail("记录缺少键 key")),
193	        };
194	
195	        let fields = match object.remove("fields") {
196	            Some(Value::Object(fields)) => fields,
197	            Some(_) => return Err(fail("记录的 fields 必须是 JSON 对象")),
198	            None => return Err(fail("记录缺少字段集 fields")),
199	        };
200	
201	        if !seen.insert(key.clone()) {
202	            return Err((
203	                StatusCode::CONFLICT,
204	                Json(ErrorBody {
205	                    error: format!("批次内出现重复键: {key}"),
206	                    index: Some(index),
207	                }),
208	            ));
209	        }
210	
211	        batch.push((key, fields));
212	    }
213	
214	    // 全部合法：持锁整体覆盖写入。任一条非法都在上面提前返回，数据集保持原状。
215	    let mut store = state.store.lock().unwrap();
216	    let written = batch.len();
217	    for (key, fields) in batch {
218	        store.dataset.insert(key, fields);
219	    }
220	    Ok(Json(WriteResponse {
221	        written,
222	        total: store.dataset.len(),
223	    }))
224	}
