244	) -> Result<axum::response::Response, (StatusCode, Json<ErrorBody>)> {
245	    let params = parse_snapshot_query(req.uri()).map_err(bad_request)?;
246	
247	    let store = state.store.lock().unwrap();
248	    let snapshot = store
249	        .snapshots
250	        .iter()
251	        .find(|s| s.version == params.version)
252	        .cloned()
253	        .ok_or_else(|| {
254	            (
255	                StatusCode::NOT_FOUND,
256	                Json(ErrorBody {
257	                    error: format!("版本 {} 不存在或尚未保存", params.version),
258	                    index: None,
259	                }),
260	            )
261	        })?;
262	
263	    match params.key {
264	        Some(key) => {
265	            let fields = snapshot.records.get(&key).cloned().ok_or_else(|| {
266	                (
267	                    StatusCode::NOT_FOUND,
268	                    Json(ErrorBody {
269	                        error: format!("版本 {} 中不存在键 {key}", snapshot.version),
270	                        index: None,
271	                    }),
272	                )
273	            })?;
274	            Ok(Json(SnapshotRecord {
275	                version: snapshot.version,
276	                key,
277	                fields,
278	            })
279	            .into_response())
280	        }
281	        None => {
282	            // BTreeMap 的迭代顺序即键的字典序。
283	            let records = snapshot
284	                .records
285	                .into_iter()
286	                .map(|(key, fields)| RecordOut { key, fields })
287	                .collect();
288	            Ok(Json(SnapshotSummary {
289	                version: snapshot.version,
290	                records,
291	            })
292	            .into_response())
293	        }
294	    }
295	}
296	
