use axum::{
    Json, Router,
    body::Bytes,
    extract::{Request, State},
    http::{StatusCode, Uri},
    response::IntoResponse,
    routing::{get, post},
};
use percent_encoding::percent_decode_str;
use serde::Deserialize;
use serde::Serialize;
use serde_json::{Map, Value};
use std::{
    collections::{BTreeMap, HashSet},
    env,
    error::Error,
    ffi::OsStr,
    fs::{self, File},
    io::Write,
    path::{Path, PathBuf},
    sync::{Mutex, MutexGuard},
};

/// 一条记录的字段集：任意 JSON 对象。
type Fields = Map<String, Value>;
/// 当前数据集：BTreeMap 保证列出记录时按键字典序排列。
type Dataset = BTreeMap<String, Fields>;

/// 一份不可变快照：保存时刻数据集的完整深拷贝。
#[derive(Clone)]
struct Snapshot {
    version: u64,
    records: BTreeMap<String, Value>,
}

#[derive(Default)]
struct Store {
    dataset: Dataset,
    /// 已保存快照，下标 0 对应版本 1。
    snapshots: Vec<Snapshot>,
}

/// 磁盘上的状态文件布局。版本号显式存储，恢复后版本序列严格接续旧序列。
#[derive(Serialize, Deserialize)]
struct PersistedState {
    /// 固定为 1，供未来格式演进时区分。
    format: u32,
    /// 当前数据集，序列化为 [key, fields] 对的数组。
    dataset: Vec<PersistedRecord>,
    /// 已保存快照，版本号必须从 1 起严格连续。
    snapshots: Vec<PersistedSnapshot>,
}

#[derive(Serialize, Deserialize)]
struct PersistedRecord {
    key: String,
    fields: Value,
}

#[derive(Serialize, Deserialize)]
struct PersistedSnapshot {
    version: u64,
    records: Vec<PersistedRecord>,
}

#[derive(Clone)]
struct AppState {
    /// 所有读写都经过同一把锁，保证批次写入与快照保存对并发交错整体可见。
    store: std::sync::Arc<Mutex<Store>>,
    /// 状态文件路径；每次成功提交后原子重写该文件。
    data_file: std::sync::Arc<PathBuf>,
}

#[derive(Serialize)]
struct Health {
    status: &'static str,
}

#[derive(Serialize)]
struct Version {
    name: &'static str,
    version: &'static str,
}

