101	}
102	
103	#[derive(Serialize)]
104	struct SaveResponse {
105	    version: u64,
106	    total: usize,
107	}
108	
109	#[derive(Serialize)]
110	struct SnapshotSummary {
111	    version: u64,
112	    records: Vec<RecordOut>,
113	}
114	
115	#[derive(Serialize)]
116	struct SnapshotRecord {
117	    version: u64,
118	    key: String,
119	    fields: Value,
120	}
121	
122	/// GET /snapshots 查询参数：必选 version，可选 key。
123	struct SnapshotParams {
124	    version: u64,
125	    key: Option<String>,
126	}
127	
128	#[derive(Serialize)]
129	struct ErrorBody {
130	    error: String,
131	    #[serde(skip_serializing_if = "Option::is_none")]
132	    index: Option<usize>,
133	}
134	
135	fn bad_request(message: impl Into<String>) -> (StatusCode, Json<ErrorBody>) {
136	    (
137	        StatusCode::BAD_REQUEST,
138	        Json(ErrorBody {
139	            error: message.into(),
140	            index: None,
141	        }),
