145	fn server_error(message: impl Into<String>) -> (StatusCode, Json<ErrorBody>) {
146	    (
147	        StatusCode::INTERNAL_SERVER_ERROR,
148	        Json(ErrorBody {
149	            error: message.into(),
150	            index: None,
