154	
155	/// 给路径末尾再追加一个扩展名：`vde-state.json` -> `vde-state.json.tmp`。
156	trait WithExtraExtension {
157	    fn with_extra_extension(&self, extra: &str) -> PathBuf;
158	}
159	
160	impl WithExtraExtension for Path {
161	    fn with_extra_extension(&self, extra: &str) -> PathBuf {
162	        let mut file_name = self.file_name().map(OsStr::to_owned).unwrap_or_default();
163	        file_name.push(format!(".{extra}"));
164	        self.with_file_name(file_name)
165	    }
166	}
167	
168	/// 状态文件名，位于 VDE_DATA_DIR（缺省为当前工作目录下的 data）。
169	const STATE_FILE_NAME: &str = "vde-state.json";
170	
171	fn data_file_path() -> PathBuf {
172	    let dir = env::var_os("VDE_DATA_DIR")
173	        .filter(|v| !v.is_empty())
174	        .map(PathBuf::from)
175	        .unwrap_or_else(|| PathBuf::from("data"));
176	    dir.join(STATE_FILE_NAME)
177	}
178	
179	/// 把内存状态序列化并原子替换状态文件：先写同目录临时文件并 fsync，再 rename。
180	/// 任何时刻状态文件要么是旧的完整内容、要么是新的完整内容，不会留下截断文件。
181	fn persist_store(store: &Store, data_file: &Path) -> std::io::Result<()> {
182	    let persisted = PersistedState {
183	        format: 1,
184	        dataset: store
185	            .dataset
186	            .iter()
187	            .map(|(key, fields)| PersistedRecord {
188	                key: key.clone(),
189	                fields: Value::Object(fields.clone()),
190	            })
191	            .collect(),
192	        snapshots: store
193	            .snapshots
194	            .iter()
195	            .map(|s| PersistedSnapshot {
196	                version: s.version,
197	                records: s
198	                    .records
199	                    .iter()
200	                    .map(|(key, fields)| PersistedRecord {
201	                        key: key.clone(),
202	                        fields: fields.clone(),
203	                    })
204	                    .collect(),
205	            })
206	            .collect(),
207	    };
208	
209	    // 序列化在持锁状态下完成；失败不会触及磁盘文件。
210	    let payload = serde_json::to_vec_pretty(&persisted).map_err(std::io::Error::other)?;
211	
212	    if let Some(dir) = data_file.parent() {
213	        fs::create_dir_all(dir)?;
214	    }
215	
216	    let tmp = data_file.with_extra_extension("tmp");
217	    {
218	        let mut file = File::create(&tmp)?;
219	        file.write_all(&payload)?;
220	        file.write_all(b"\n")?;
221	        file.sync_all()?;
222	    }
223	    fs::rename(&tmp, data_file)?;
224	
225	    // fsync 目录，确保 rename 本身落盘（崩溃恢复语义更稳）。
226	    if let Some(dir) = data_file.parent()
227	        && let Ok(dir_file) = File::open(dir)
228	    {
229	        let _ = dir_file.sync_all();
230	    }
231	    Ok(())
232	}
233	
234	/// 严格校验并恢复状态。文件不存在时返回空状态；文件存在但无法解析或结构不合法时
235	/// 返回错误，调用方必须拒绝启动，且本函数绝不改动原文件。
236	fn load_store(data_file: &Path) -> Result<Store, String> {
237	    let bytes = match fs::read(data_file) {
238	        Ok(bytes) => bytes,
239	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Store::default()),
240	        Err(e) => return Err(format!("无法读取状态文件 {}: {e}", data_file.display())),
241	    };
242	
243	    let persisted: PersistedState = serde_json::from_slice(&bytes).map_err(|e| {
244	        format!(
245	            "状态文件 {} 不是合法 JSON，拒绝启动: {e}",
246	            data_file.display()
247	        )
248	    })?;
249	
250	    if persisted.format != 1 {
251	        return Err(format!(
252	            "状态文件 {} 的 format 为 {}，本版本仅支持 1",
253	            data_file.display(),
254	            persisted.format
255	        ));
256	    }
257	
258	    let mut dataset: Dataset = BTreeMap::new();
259	    for record in persisted.dataset {
260	        let Value::Object(fields) = record.fields else {
261	            return Err(format!(
262	                "状态文件 {} 中数据集键 {} 的 fields 不是 JSON 对象",
263	                data_file.display(),
264	                record.key
265	            ));
266	        };
267	        if dataset.insert(record.key.clone(), fields).is_some() {
268	            return Err(format!(
269	                "状态文件 {} 的数据集中键 {} 重复",
270	                data_file.display(),
271	                record.key
272	            ));
273	        }
274	    }
275	
276	    let mut snapshots: Vec<Snapshot> = Vec::with_capacity(persisted.snapshots.len());
277	    for (index, snap) in persisted.snapshots.into_iter().enumerate() {
278	        let expected = index as u64 + 1;
279	        if snap.version != expected {
280	            return Err(format!(
281	                "状态文件 {} 的快照版本序列不连续：第 {} 份快照版本为 {}，应为 {}",
282	                data_file.display(),
283	                expected,
284	                snap.version,
285	                expected
286	            ));
287	        }
288	        let mut records: BTreeMap<String, Value> = BTreeMap::new();
289	        for record in snap.records {
290	            let Value::Object(_) = &record.fields else {
291	                return Err(format!(
292	                    "状态文件 {} 中版本 {} 键 {} 的 fields 不是 JSON 对象",
293	                    data_file.display(),
294	                    snap.version,
295	                    record.key
296	                ));
297	            };
298	            if records.insert(record.key.clone(), record.fields).is_some() {
299	                return Err(format!(
300	                    "状态文件 {} 的版本 {} 中键 {} 重复",
301	                    data_file.display(),
302	                    snap.version,
303	                    record.key
304	                ));
305	            }
306	        }
307	        snapshots.push(Snapshot {
308	            version: snap.version,
309	            records,
310	        });
311	    }
312	
313	    Ok(Store { dataset, snapshots })
314	}
315	
316	/// 手动解析查询串（percent-decode 后取 version / key）。
317	fn parse_snapshot_query(uri: &Uri) -> Result<SnapshotParams, String> {
318	    let mut version: Option<u64> = None;
319	    let mut key: Option<String> = None;
320	    if let Some(query) = uri.query() {
321	        for pair in query.split('&') {
322	            let Some((raw_name, raw_value)) = pair.split_once('=') else {
323	                return Err(format!("非法查询参数: {pair}"));
324	            };
325	            let name = percent_decode_str(raw_name).decode_utf8_lossy();
326	            let value = percent_decode_str(raw_value).decode_utf8_lossy();
327	            match name.as_ref() {
328	                "version" => {
329	                    version = Some(
330	                        value
331	                            .parse()
332	                            .map_err(|_| format!("version 必须是正整数: {value}"))?,
333	                    );
334	                }
335	                "key" => key = Some(value.into_owned()),
336	                other => return Err(format!("未知查询参数: {other}")),
337	            }
338	        }
339	    }
340	    match version {
341	        Some(version) => Ok(SnapshotParams { version, key }),
342	        None => Err("缺少必填查询参数 version".to_owned()),
343	    }
344	}
345	
346	async fn health() -> Json<Health> {
347	    Json(Health { status: "ok" })
348	}
349	
350	async fn version() -> Json<Version> {
351	    Json(Version {
352	        name: env!("CARGO_PKG_NAME"),
353	        version: env!("CARGO_PKG_VERSION"),
354	    })
355	}
