357	/// POST /datasets/records：整体成功或整体失败的批量写入。
358	async fn write_records(
359	    State(state): State<AppState>,
360	    body: Bytes,
361	) -> Result<Json<WriteResponse>, (StatusCode, Json<ErrorBody>)> {
362	    // 解析与全部校验都在锁外完成；只有整批合法时才持锁一次性提交。
363	    let parsed: WriteRequest = serde_json::from_slice(&body)
364	        .map_err(|e| bad_request(format!("请求必须是包含 records 数组的 JSON 对象: {e}")))?;
365	
366	    if parsed.records.is_empty() {
367	        return Err(bad_request("records 不能为空批次"));
368	    }
369	
370	    let mut seen = HashSet::with_capacity(parsed.records.len());
371	    let mut batch: Vec<(String, Fields)> = Vec::with_capacity(parsed.records.len());
372	
373	    for (index, record) in parsed.records.into_iter().enumerate() {
374	        let fail = |message: &'static str| {
375	            (
376	                StatusCode::BAD_REQUEST,
377	                Json(ErrorBody {
378	                    error: message.to_owned(),
379	                    index: Some(index),
380	                }),
381	            )
382	        };
383	
384	        let mut object = match record {
385	            Value::Object(map) => map,
386	            _ => return Err(fail("每条记录必须是 JSON 对象")),
387	        };
388	
389	        let key = match object.remove("key") {
390	            Some(Value::String(key)) => key,
391	            Some(_) => return Err(fail("记录的 key 必须是字符串")),
392	            None => return Err(fail("记录缺少键 key")),
393	        };
394	
395	        let fields = match object.remove("fields") {
396	            Some(Value::Object(fields)) => fields,
397	            Some(_) => return Err(fail("记录的 fields 必须是 JSON 对象")),
398	            None => return Err(fail("记录缺少字段集 fields")),
399	        };
400	
401	        if !seen.insert(key.clone()) {
402	            return Err((
403	                StatusCode::CONFLICT,
404	                Json(ErrorBody {
405	                    error: format!("批次内出现重复键: {key}"),
406	                    index: Some(index),
407	                }),
408	            ));
409	        }
410	
411	        batch.push((key, fields));
412	    }
413	
414	    // 全部合法：持锁整体覆盖写入，并在同一临界区把新状态落盘。
415	    // 落盘失败则精确回滚本批改动、返回 500，数据集保持请求前状态。
416	    let mut store = state.store.lock().unwrap();
417	    let mut previous: Vec<(String, Option<Fields>)> = Vec::with_capacity(batch.len());
418	    for (key, fields) in &batch {
419	        previous.push((key.clone(), store.dataset.get(key).cloned()));
420	        store.dataset.insert(key.clone(), fields.clone());
421	    }
422	    if let Err(e) = persist_store(&store, &state.data_file) {
423	        for (key, old) in previous {
424	            match old {
425	                Some(fields) => {
426	                    store.dataset.insert(key, fields);
427	                }
428	                None => {
429	                    store.dataset.remove(&key);
430	                }
431	            }
432	        }
433	        return Err(server_error(format!("状态落盘失败: {e}")));
434	    }
435	    let total = store.dataset.len();
436	    Ok(Json(WriteResponse {
437	        written: batch.len(),
438	        total,
439	    }))
440	}
441	
442	/// POST /versions：把当前数据集固化为不可变快照。
443	async fn save_version(
444	    State(state): State<AppState>,
445	) -> Result<Json<SaveResponse>, (StatusCode, Json<ErrorBody>)> {
446	    let mut store: MutexGuard<Store> = state.store.lock().unwrap();
447	    let version = store.snapshots.len() as u64 + 1;
448	    let records = store
449	        .dataset
450	        .iter()
451	        .map(|(key, fields)| (key.clone(), Value::Object(fields.clone())))
452	        .collect();
453	    let total = store.dataset.len();
454	    store.snapshots.push(Snapshot { version, records });
455	
456	    // 与写入同一套原子提交：落盘失败则撤回刚追加的快照。
457	    if let Err(e) = persist_store(&store, &state.data_file) {
458	        store.snapshots.pop();
459	        return Err(server_error(format!("状态落盘失败: {e}")));
460	    }
461	    Ok(Json(SaveResponse { version, total }))
462	}
463	
464	/// GET /snapshots?version=N[&key=K]：读取历史快照。
465	async fn get_snapshot(
466	    State(state): State<AppState>,
467	    req: Request,
468	) -> Result<axum::response::Response, (StatusCode, Json<ErrorBody>)> {
469	    let params = parse_snapshot_query(req.uri()).map_err(bad_request)?;
470	
471	    let store = state.store.lock().unwrap();
472	    let snapshot = store
473	        .snapshots
474	        .iter()
475	        .find(|s| s.version == params.version)
476	        .cloned()
477	        .ok_or_else(|| {
478	            (
479	                StatusCode::NOT_FOUND,
480	                Json(ErrorBody {
481	                    error: format!("版本 {} 不存在或尚未保存", params.version),
482	                    index: None,
483	                }),
484	            )
485	        })?;
486	
487	    match params.key {
488	        Some(key) => {
489	            let fields = snapshot.records.get(&key).cloned().ok_or_else(|| {
490	                (
491	                    StatusCode::NOT_FOUND,
492	                    Json(ErrorBody {
493	                        error: format!("版本 {} 中不存在键 {key}", snapshot.version),
494	                        index: None,
495	                    }),
496	                )
497	            })?;
498	            Ok(Json(SnapshotRecord {
499	                version: snapshot.version,
500	                key,
501	                fields,
502	            })
503	            .into_response())
504	        }
505	        None => {
506	            // BTreeMap 的迭代顺序即键的字典序。
507	            let records = snapshot
508	                .records
509	                .into_iter()
510	                .map(|(key, fields)| RecordOut { key, fields })
511	                .collect();
512	            Ok(Json(SnapshotSummary {
513	                version: snapshot.version,
514	                records,
515	            })
516	            .into_response())
517	        }
518	    }
519	}
520	
521	#[tokio::main]
522	async fn main() -> Result<(), Box<dyn Error>> {
523	    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
524	    let data_file = std::sync::Arc::new(data_file_path());
525	
526	    // 启动恢复必须在对外服务之前完成：文件损坏则报错到 stderr 并非零退出，
527	    // 不绑定端口、不载入半份数据、也不改动原文件。
528	    let store = match load_store(&data_file) {
529	        Ok(store) => store,
530	        Err(message) => {
531	            eprintln!("{message}");
532	            std::process::exit(1);
533	        }
534	    };
535	    if data_file.exists() {
536	        eprintln!(
537	            "已从 {} 恢复：数据集 {} 条记录，快照 {} 个版本",
538	            data_file.display(),
539	            store.dataset.len(),
540	            store.snapshots.len()
541	        );
542	    } else {
543	        eprintln!(
544	            "状态文件 {} 不存在，以空数据集启动（尚无快照）",
545	            data_file.display()
546	        );
547	    }
548	
549	    let state = AppState {
550	        store: std::sync::Arc::new(Mutex::new(store)),
551	        data_file,
552	    };
553	    let app = Router::new()
554	        .route("/health", get(health))
555	        .route("/version", get(version))
556	        .route("/datasets/records", post(write_records))
557	        .route("/versions", post(save_version))
558	        .route("/snapshots", get(get_snapshot))
559	        .with_state(state);
560	
561	    let listener = tokio::net::TcpListener::bind(&bind).await?;
562	    println!("Listening on http://{}", listener.local_addr()?);
563	    axum::serve(listener, app)
564	        .with_graceful_shutdown(async {
565	            let _ = tokio::signal::ctrl_c().await;
566	        })
567	        .await?;
568	    Ok(())
569	}
